css:
.diary-shell { --diary-pink: #f6dbe4; --diary-pink-strong: #e39cb4; --diary-border: #e8e3e3;
  --diary-text: #2b2b2b; --diary-muted: #8b8b8b; --diary-bg-side: #fdf7f9;
  display: flex; align-items: flex-start; gap: 0; max-width: 1040px; margin: 0 auto;
  background: #ffffff; color: var(--diary-text); font-family: "Pretendard", "Apple SD Gothic Neo", system-ui, sans-serif;
  font-size: 15px; line-height: 1.6; box-sizing: border-box; }
.diary-shell *, .diary-shell *::before, .diary-shell *::after { box-sizing: border-box; }
.diary-sidebar { width: 240px; flex: 0 0 240px; border-right: 1px solid var(--diary-border);
  background: var(--diary-bg-side); padding: 28px 20px; }
.diary-brand { margin-bottom: 20px; }
.diary-site-title { margin: 0; font-size: 18px; font-weight: 700; letter-spacing: -0.02em; }
.diary-profile { padding-bottom: 20px; border-bottom: 1px solid var(--diary-border); margin-bottom: 20px; }
.diary-avatar { width: 72px; height: 72px; border-radius: 4px; object-fit: cover; display: block;
  background: var(--diary-pink); border: 1px solid var(--diary-border); margin-bottom: 10px; }
.diary-nickname { margin: 0 0 6px; font-size: 15px; font-weight: 600; }
.diary-bio { margin: 0; font-size: 13px; color: var(--diary-muted); word-break: keep-all; }
.diary-home-link { display: block; margin-bottom: 18px; padding: 8px 10px; background: var(--diary-pink);
  color: var(--diary-text); text-decoration: none; font-size: 13px; font-weight: 700; text-align: center; }
.diary-nav-section, .diary-banner-section { margin-bottom: 18px; }
.diary-nav-label { margin: 0 0 8px; font-size: 11px; letter-spacing: 0.08em; color: var(--diary-muted); }
.diary-nav-list, .diary-banner-list { list-style: none; margin: 0; padding: 0; }
.diary-nav-list li, .diary-banner-list li { border-bottom: 1px solid var(--diary-border); }
.diary-nav-list a, .diary-banner-list a { display: block; padding: 8px 2px; color: var(--diary-text);
  text-decoration: none; font-size: 14px; }
.diary-nav-list a:hover, .diary-banner-list a:hover { color: var(--diary-pink-strong); }
.diary-main { flex: 1 1 auto; min-width: 0; padding: 32px 36px; }
.diary-hero { margin-bottom: 24px; }
.diary-greeting { margin: 0; font-size: 15px; color: var(--diary-muted); }
.diary-section-title { margin: 0 0 16px; font-size: 17px; font-weight: 700; padding-bottom: 10px;
  border-bottom: 2px solid var(--diary-pink); }
.diary-category-header { margin-bottom: 8px; }
.diary-post-list { list-style: none; margin: 0; padding: 0; }
.diary-post-item { border-bottom: 1px solid var(--diary-border); }
.diary-post-link { display: flex; align-items: baseline; gap: 8px; padding: 12px 4px; text-decoration: none;
  color: var(--diary-text); flex-wrap: wrap; }
.diary-post-title { font-size: 15px; font-weight: 600; word-break: keep-all; }
.diary-post-link:hover .diary-post-title { color: var(--diary-pink-strong); }
.diary-post-secret { font-size: 11px; font-weight: 700; color: var(--diary-pink-strong);
  border: 1px solid var(--diary-pink-strong); padding: 1px 6px; }
.diary-post-date { margin-left: auto; font-size: 12px; color: var(--diary-muted); white-space: nowrap; }
.diary-post-list:empty::after { content: "아직 작성된 글이 없습니다."; display: block; padding: 24px 4px;
  color: var(--diary-muted); font-size: 13px; }
.diary-breadcrumb { margin-bottom: 12px; }
.diary-breadcrumb a { font-size: 13px; color: var(--diary-pink-strong); text-decoration: none;
  border: 1px solid var(--diary-pink-strong); padding: 3px 10px; }
.diary-post-detail-title { margin: 4px 0 8px; font-size: 22px; font-weight: 700; line-height: 1.4;
  word-break: keep-all; overflow-wrap: break-word; }
.diary-post-detail-date { margin: 0 0 24px; font-size: 12px; color: var(--diary-muted); }
.diary-post-body { border-top: 1px solid var(--diary-border); padding-top: 20px; max-width: 100%; }

@media (max-width: 720px) {
  .diary-shell { flex-direction: column; }
  .diary-sidebar { width: 100%; flex: 1 1 auto; border-right: none; border-bottom: 1px solid var(--diary-border); }
  .diary-main { padding: 24px 18px; }
  .diary-post-link { flex-direction: column; align-items: flex-start; gap: 2px; }
  .diary-post-date { margin-left: 0; white-space: normal; overflow-wrap: anywhere; }
}
